      SUBROUTINE CMISDO(CMIS)CC     CREATE LITERAL DESCRIPTIONS FROM INTERNALLY STORED MISALIGNMENTC     CODEC      CHARACTER*20    CMIS      INCLUDE 'ELM8A.CIN'      INCLUDE 'RDCHAR.CIN'      CHARACTER*2     CR1, CR2      CHARACTER*3     CUNC      CHARACTER*4     CBEAM      CHARACTER*5     CBENDS, CKNOWN, CQUADS, CTABLE      CHARACTER*6     CRAND, CSING      CHARACTER*7     CMAG      INTEGER         NMIN, NMAX      DATA            CUNC   /'UNC'/      DATA            CKNOWN /'KNOWN'/      DATA            CRAND  /'RANDOM'/      DATA            CBEAM  /'BEAM'/      DATA            CTABLE /'TABLE'/      DATA            CSING  /'SINGLE'/      DATA            CR1    /'R1'/      DATA            CR2    /'R2'/      DATA            CMAG   /'MAGNETS'/      DATA            CBENDS /'BENDS'/      DATA            CQUADS /'QUADS'/C      CMIS = BLANK      IF (LFM .EQ. 0) THEN        CMIS(1:3) = CUNC        NMIN = 4      ELSE IF (LFM .EQ. 1) THEN        CMIS(1:5) = CKNOWN        NMIN = 6      ELSE IF (LFM .EQ. 2) THEN        CMIS(1:6) = CRAND        NMIN = 7      ENDIFC      CMIS(NMIN:NMIN) = SLASH      NMIN = NMIN + 1C      IF (RORC .EQ. 0) THEN        NMAX = NMIN + 5        CMIS(NMIN:NMAX) = CSING      ELSE IF (RORC .EQ. 1) THEN        NMAX = NMIN + 1        CMIS(NMIN:NMAX) = CR1       ELSE IF (RORC .EQ. 2) THEN        NMAX = NMIN + 1        CMIS(NMIN:NMAX) = CR2      ELSE IF (RORC .EQ. 3) THEN        NMAX = NMIN + 6        CMIS(NMIN:NMAX) = CMAG      ELSE IF (RORC .EQ. 4) THEN        NMAX = NMIN + 4        CMIS(NMIN:NMAX) = CBENDS      ELSE IF (RORC .EQ. 5) THEN        NMAX = NMIN + 4        CMIS(NMIN:NMAX) = CQUADS      ENDIF C      NMIN = NMAX + 1      CMIS(NMIN:NMIN) = SLASH      NMIN = NMIN + 1C      IF (LTAB .EQ. 0) THEN        NMAX = NMIN + 3        CMIS(NMIN:NMAX) = CBEAM      ELSE IF (LTAB .EQ. 1) THEN        NMAX = NMIN + 4        CMIS(NMIN:NMAX) = CTABLE      ENDIF      RETURN      END